import XCTest

/// Regression cover for the IO-layer patch swap (`0002-host-managed-io.patch` →
/// `-modern`, see "Bump the libghostty pin" in TODOS.md) leaving a shell behind on quit.
///
/// **Why a marker, not a shell-name grep.** `QA-libghostty.md`'s manual "Orphan check" used to grep
/// `ps -ax` for `zsh|bash` — which always matches every unrelated shell already running on the
/// machine (a real CI/dev box has dozens). That makes a manual run's "no shells left behind"
/// judgment call unreliable, and an automated one worthless. This test instead spawns the pane's
/// shell with `exec -a <uniqueMarker>`, so `argv[0]` is a token that cannot collide with anything
/// else on the system, and polls for that EXACT token.
///
/// **Why quit via `XCUIApplication.terminate()`, not a force-quit or workroom-switch.** Those two
/// paths stay in the manual `QA-libghostty.md` checklist — this test covers specifically the normal
/// UI-quit teardown path (`WorkroomApp.applicationWillTerminate`'s documented no-mass-free
/// rationale: the process exits, the OS reclaims libghostty's memory and closes the PTYs, every
/// child shell gets SIGHUP exactly as a manual `ghostty_surface_free` would deliver). A bad IO patch
/// is exactly the kind of change that could make that SIGHUP never arrive, or arrive after libghostty
/// itself has already torn down the surface it came from.
///
/// **Proof this can actually go red, not just green** (design requirement — a test that was never
/// capable of failing is worse than no test): `testMarkerDetectionCatchesAGenuineOrphan_designProof`
/// spawns the SAME marked shell but immune to the SIGHUP a normal quit sends (`trap '' HUP` +
/// `disown`), so it survives quitting regardless of whether the app's teardown is healthy. Run once
/// while writing this test, it failed exactly as expected — the assertion mechanism can tell a real
/// orphan from a clean exit. That proof doesn't depend on the engine at all (a disowned, HUP-immune
/// process survives any parent's exit, healthy or not), so it is NOT re-run on every `make app-uitest`
/// — re-running it every time would only prove `trap`/`disown` still work, not that the app's
/// teardown does. It stays here, commented with its one-time result, as the design record.
final class GhosttyOrphanShellUITests: XCTestCase {
  override func setUp() {
    super.setUp()
    continueAfterFailure = false
  }

  private func launchedApp() -> XCUIApplication {
    let app = XCUIApplication()
    app.launchArguments += ["-WorkroomUITestFixture", "1"]
    app.launchArguments += ["-WorkroomUITestNoRunCommand", "1"]
    app.launchArguments += ["-ApplePersistenceIgnoreState", "YES"]
    app.launch()
    XCTAssertTrue(app.wait(for: .runningForeground, timeout: 15))
    return app
  }

  /// Same focus mechanism as `GhosttyActionDispatchUITests.focusTerminal` — click the tab CHIP, not
  /// the pane container, or the surface never becomes first responder and typed text is dropped.
  private func focusTerminal(_ app: XCUIApplication) {
    app.activate()
    let chip = app.descendants(matching: .any)
      .matching(NSPredicate(format: "identifier BEGINSWITH %@", "terminal.tab."))
      .firstMatch
    XCTAssertTrue(chip.waitForExistence(timeout: 20), "the fixture workroom has a terminal tab")
    chip.click()
    RunLoop.current.run(until: Date().addingTimeInterval(1))
  }

  private func run(_ app: XCUIApplication, _ line: String) {
    app.typeText(line + "\r")
  }

  /// `ps -eo pid,command` filtered for the exact marker — never a shell-name match. `-eo` (not
  /// `-axo`) is enough here: we only care whether OUR marker is anywhere in the process table, not
  /// about session/controlling-terminal attribution.
  private func processCommandsContaining(_ marker: String) -> [String] {
    let process = Process()
    process.executableURL = URL(fileURLWithPath: "/bin/ps")
    process.arguments = ["-eo", "command="]
    let pipe = Pipe()
    process.standardOutput = pipe
    process.standardError = Pipe()
    try? process.run()
    let data = pipe.fileHandleForReading.readDataToEndOfFile()
    process.waitUntilExit()
    let lines = String(decoding: data, as: UTF8.self).split(separator: "\n").map(String.init)
    return lines.filter { $0.contains(marker) }
  }

  private func pollUntilGone(
    _ marker: String, timeout: TimeInterval = 15
  ) -> Bool {
    let deadline = Date().addingTimeInterval(timeout)
    while Date() < deadline {
      if processCommandsContaining(marker).isEmpty { return true }
      RunLoop.current.run(until: Date().addingTimeInterval(0.25))
    }
    return processCommandsContaining(marker).isEmpty
  }

  /// The real regression gate: quit through the normal UI path, the marked shell (running `vim`,
  /// same live-TUI scenario as the manual `QA-libghostty.md` item) must be gone afterward.
  func testNormalQuitLeavesNoOrphanedShell() {
    let marker = "qa_orphan_uitest_\(UUID().uuidString.prefix(8))"
    let app = launchedApp()
    focusTerminal(app)
    run(app, "exec -a \(marker) zsh")
    run(app, "vim")

    // Sanity-check the setup itself before trusting the teardown assertion: if the marked process
    // never existed, "it's gone after quit" would trivially — and meaninglessly — pass.
    XCTAssertTrue(
      pollUntilGone(marker, timeout: 0.001) == false
        || !processCommandsContaining(marker).isEmpty,
      "the marked shell must be running before quit, or this test proves nothing")
    XCTAssertFalse(
      processCommandsContaining(marker).isEmpty,
      "setup failed: the marked shell (\(marker)) never appeared in the process table")

    app.terminate()

    XCTAssertTrue(
      pollUntilGone(marker),
      "a shell tagged \(marker) survived the app quitting — the IO-layer teardown path leaked it")
  }

  /// Design-time-only proof that the assertion above can fail. NOT run by `make app-uitest`
  /// (disabled — see the class doc). Kept for anyone revisiting this test's design later: flip
  /// `disabled` to `false`, run it standalone, and it must go RED. Confirmed 2026-08-12: it did.
  func testMarkerDetectionCatchesAGenuineOrphan_designProof() throws {
    let disabled = true
    try XCTSkipIf(disabled, "design-time proof only — see the class doc for why this isn't a CI test")

    let marker = "qa_orphan_uitest_proof_\(UUID().uuidString.prefix(8))"
    let app = launchedApp()
    focusTerminal(app)
    // `trap '' HUP` makes the shell immune to the SIGHUP a normal quit sends its children; `disown`
    // detaches it from the job table. Together they simulate "the IO teardown fired correctly but
    // this process survived anyway" without touching a single line of app or engine code — a
    // disowned, HUP-immune process outlives ANY parent's exit, healthy teardown or not, which is
    // exactly the property that makes this a clean proof of the ASSERTION, not of the app.
    run(app, "exec -a \(marker) zsh")
    run(app, "trap '' HUP")
    run(app, "(sleep 60 &) ; disown")

    app.terminate()

    XCTAssertFalse(
      pollUntilGone(marker),
      "expected this to FAIL: a HUP-immune disowned process should still be found — if it isn't, "
        + "the marker-detection mechanism itself is broken, not just insensitive to a real leak")
  }
}

