  /// (disabled — see the class doc). Kept for anyone revisiting this test's design later: flip
  /// `disabled` to `false`, run it standalone, and it must go RED. Confirmed 2026-08-12: it did.
  func testMarkerDetectionCatchesAGenuineOrphan_designProof() throws {
    let disabled = false
    try XCTSkipIf(
      disabled, "design-time proof only — see the class doc for why this isn't a CI test")

    let marker = "qa_orphan_uitest_proof_\(UUID().uuidString.prefix(8))"
    let app = launchedApp()
    focusTerminal(app)
    // The marker must be on the process meant to OUTLIVE the quit, not on the interactive shell
    // itself — the shell dies on PTY read-EOF regardless of any HUP trap (that's an EOF exit, not a
    // signal), so a marked shell proves nothing here. `disown` detaches the backgrounded `sleep` from
    // the job table so the shell exiting doesn't wait on or reap it; that alone is enough to simulate
    // "survives the app quitting" without touching a single line of app or engine code.
    run(app, "(exec -a \(marker) sleep 60 &) ; disown")

    let surface = app.descendants(matching: .any).matching(
      NSPredicate(format: "identifier == %@", "terminal.surface")
    ).firstMatch
    print("DEBUG surface value: \(String(describing: surface.value))")

    // Same sanity check the real test makes — without it, "found" vs. "never existed" are
    // indistinguishable from a bare pass/fail.
    XCTAssertTrue(
      pollUntilAppears(marker),
      "setup failed: the marked background process (\(marker)) never appeared in the process table")

    app.terminate()

    XCTAssertFalse(
      pollUntilGone(marker),
      "expected this to FAIL: a disowned background process should still be found after quit — if "
        + "it isn't, the marker-detection mechanism itself is broken, not just insensitive to a real "
        + "leak")
  }
}

