    let surface = app.descendants(matching: .any).matching(
      NSPredicate(format: "identifier == %@", "terminal.surface")
    ).firstMatch
    print("DEBUG surface value 1: \(String(describing: surface.value))")
    RunLoop.current.run(until: Date().addingTimeInterval(3))
    print("DEBUG surface value 2 (+3s): \(String(describing: surface.value))")
    let spikeFile = URL(fileURLWithPath: NSTemporaryDirectory())
      .appendingPathComponent("qa-orphan-spike-\(UUID().uuidString).txt")
